static void GCC_FMT_ATTR (2, 3) oss_logerr (int err, const char *fmt, ...) /* <=== oss_logerr */ 
{
    va_list ap;

    va_start (ap, fmt);
    AUD_vlog (AUDIO_CAP, fmt, ap);
    va_end (ap);

    AUD_log (AUDIO_CAP, "Reason: %s\n", strerror (err));
}

static size_t oss_get_available_bytes(OSSVoiceOut *oss) /* <=== oss_get_available_bytes */ 
{
    int err;
    struct count_info cntinfo;
    assert(oss->mmapped);

    err = ioctl(oss->fd, SNDCTL_DSP_GETOPTR, &cntinfo);
    if (err < 0) {
        oss_logerr(errno, "SNDCTL_DSP_GETOPTR failed\n");
        return 0;
    }

    return audio_ring_dist(cntinfo.ptr, oss->hw.pos_emul, oss->hw.size_emul);
}

static inline size_t audio_ring_dist(size_t dst, size_t src, size_t len) /* <=== audio_ring_dist */ 
{
    return (dst >= src) ? (dst - src) : (len - src + dst);
}

